-- 0087_template_drafts.sql
--
-- Templates become editable from Admin, with the database as the master copy:
--   * draft_config / draft_version / draft_updated_at: the admin's unpublished
--     edit of the template (the live version stays in template_versions).
--   * meta: what the code templates carry beside the config (page names in both
--     languages, the preview catalog, the palette), filled once below.
--   * deleted_at: soft delete.
-- Template seed migrations are insert-only from here on (templateSeedSql).
--
-- Idempotent. The UPDATE statements are generated by
-- `pnpm --filter @workspace/store-sections template:meta-sql` and only touch rows whose meta is still empty.

ALTER TABLE templates
  ADD COLUMN IF NOT EXISTS draft_config jsonb,
  ADD COLUMN IF NOT EXISTS draft_version integer NOT NULL DEFAULT 1,
  ADD COLUMN IF NOT EXISTS draft_updated_at timestamptz,
  ADD COLUMN IF NOT EXISTS meta jsonb NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS deleted_at timestamptz;

